{
  "description": "The creature is a large quadrupedal animal shown in right-facing profile against a plain off-white background. It has the overall body shape, dense shaggy brown fur, and head shape of a bear, but its back, neck, shoulders, hips, and lower legs are covered by a glossy, hard-looking, dark brown to black segmented covering with a smooth shiny surface and distinct plate boundaries that resembles a beetle's exoskeleton. The head is bear-like with a blunt snout, dark nose, small brown eyes, and rounded furry ears, topped by a smooth helmet-like plate from which a single long, upward and forward curving horn with small tooth-like spines on its inner edge projects. It stands on four thick furry legs ending in large clawed paws, with a small pointed segmented tail at the rear. Fur is visible on the head, neck, chest, belly, and legs beneath and between the dark plates.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with shaggy brown fur, lighter tan around the muzzle, a large dark brown-black nose at the tip of the snout, small round brown eyes, and a closed mouth, facing to the right",
      "where": "at the front end of the body, attached to the neck"
    },
    {
      "part": "horns",
      "looks_like": "one long, glossy dark brown-black, smooth, sharply pointed horn that curves up and forward, with several small pointed spines along its inner concave edge, arising from a smooth helmet-like plate",
      "where": "on top of the head, centered on the helmet plate between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with dense fur",
      "where": "on the sides of the top of the head, protruding from under the edges of the helmet plate, one on each side behind the horn base"
    },
    {
      "part": "legs",
      "looks_like": "four thick, sturdy, heavily furred brown legs with shaggy fur, each partially covered by glossy dark segmented plates on the upper and lower sections",
      "where": "under the body, two front legs supporting the chest and two hind legs supporting the hips, in a standing posture"
    },
    {
      "part": "feet",
      "looks_like": "four large bear paws with brown fur on top and long, curved, dark claws on the toes, with visible pads underneath",
      "where": "at the bottom ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a small, short, pointed, glossy dark segmented tail with overlapping plates tapering to a tip",
      "where": "at the rear end of the body, extending back from the hindquarters"
    },
    {
      "part": "plates",
      "looks_like": "extensive glossy dark brown to black hard plates with smooth shiny surfaces and thin dividing lines between segments, forming a segmented covering",
      "where": "covering the dorsal back from neck to tail, the sides of the neck, the shoulders, the outer hips/thighs, and the front and back of the lower legs, overlying the brown fur"
    },
    {
      "part": "shell",
      "looks_like": "same glossy dark segmented hard covering as the plates, forming a continuous carapace-like shell over the back and neck with large smooth dorsal segments and smaller overlapping segments on the neck and tail",
      "where": "on the back, neck, and tail, forming the main dorsal armor"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "rhinoceros beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
